"""Source review 8–16 of chapter XIII: full turn, arc length, units, area, sector and segment."""
import argparse
import json
from math import pi
from circle_length_applications import arc
from circumference_lengths import drawing
from disk_area_table import scene as inscribed
from regular_polygon_review import ask
from sector_areas import disk
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/circle-measure-review.json'


def boundary():
    first=ask(8,'Свяжи полный оборот и длину окружности','Выведи формулу длины всей окружности. Объясни, как в вычислении появляется её градусная мера 360°.',
      'Весь круговой путь соответствует 360°. Пусть R — радиус, d=2R. Для всех окружностей отношение длины C к диаметру одно и то же, его обозначают π. Получаем C=πd=2πR. В градусной записи дуга в 1° имеет длину C/360; все 360 таких дуг вместе дают 2πR.',
      '360° измеряют поворот, а не длину. Чтобы получить длину в сантиметрах, нужно знать радиус или диаметр.',[
      ('Измерь полный оборот','Развёртка границы даёт длину PE. Диаметр BA в π раз меньше. Когда R=2, диаметр 4, поэтому полный путь имеет длину 4π.','Длина определяется по границе; через центр измеряют диаметр.'),
      ('Сверь по градусам','Угол 90° задаёт 1/4 полного пути. Для R=2 каждая из четырёх дуг по 90° имеет длину π. Сложив их, снова получишь 4π.','Четыре раза складываем длины дуг, а не хорды.'),
      ('Измени диаметр','У новой окружности R=5, d=10. В 360° по-прежнему полный оборот, а его длина уже 10π.','Угловая мера полного оборота не меняется при увеличении радиуса.')],
      [drawing('Развёртка окружности R=2',2,unroll=True),drawing('Четверть оборота',2,quarter=True),drawing('Полный оборот R=5',5,unroll=True)],
      [('Сколько дуг по 90° замыкают окружность?','4','Раздели 360 на 90.'),('Каков коэффициент при π в C для R=5?','10','Коэффициент равен диаметру.')],[118],
      'BA — диаметр, UV — единица. PE на схемах развёртки равно длине полного оборота.')
    second=ask(9,'Определи число π','Что обозначает число π и какое приближённое значение можно использовать? Объясни его на двух разных окружностях.',
      'Число π — отношение длины любой окружности к её диаметру. Численно π=3,14159265…; например, до сотых 3,14. Это безразмерное отношение, так как и длина, и диаметр измерены в одной единице.',
      'Если в знаменателе радиус, получишь 2π. Для определения π дели длину именно на диаметр.',[
      ('Найди знаменатель','У окружности R=1 диаметр 2, её длина 2π. Отношение к диаметру π, а к радиусу 2π.','Делить одну и ту же границу на разные отрезки — разные вычисления.'),
      ('Проверь при увеличении','При удвоении R увеличиваются вдвое и длина границы, и диаметр. Их частное не изменяется. На чертеже сравни отрезок PE с BA.','Множители масштаба в числителе и знаменателе сокращаются.'),
      ('Округли осмысленно','При диаметре 10 применение 3,14 даёт длину 31,4. При использовании клавиши π получишь 31,4159…; отличие вызвано округлением.','Число 3,14 — приближённое значение, поэтому не заменяй знак приближённого равенства точным.')],
      [drawing('Окружность радиуса 1',1,unroll=True),drawing('Диаметр увеличен вдвое',2,unroll=True),drawing('Диаметр 10',5,unroll=True)],
      [('На какую длину делят C при R=1, чтобы получить π?','2','Нужен диаметр.'),('Чему равна длина при d=10 и π≈3,14?','31,4','Умножь 10 на 3,14.')],[118],
      'UV — одна единица. PE измеряет длину границы, BA — диаметр. Сравни их отношение при разных масштабах.')
    third=ask(10,'Длина дуги в градусах','Выведи формулу длины дуги радиуса R, если её градусная мера равна α.',
      'Дуга с мерой α° составляет α/360 от окружности. Умножая C=2πR на эту долю, получаем l=παR/180.',
      'В доле α/360 числитель — градусы, знаменатель — градусы полного оборота. Не подставляй сюда угол в радианах.',[
      ('Отдели долю оборота','В первом круге R=3. Дуга 60° составляет одну шестую от 6π, значит её длина π.','Для хорды AB понадобилось бы другое вычисление.'),
      ('Проверь дугу больше полуокружности','При R=3 угол 240° задаёт 2/3 окружности. Получается 4π. Малый путь между теми же точками дал бы только 2π.','Выбирай ту дугу, градусная мера которой названа.'),
      ('Поменяй оба данных','При R=8 и α=45° берём восьмую часть 16π. Новая длина дуги равна 2π.','Сначала пересчитай долю, затем умножай на новый полный путь.')],
      [arc('Одна шестая окружности',3,60),arc('Большая дуга 240°',3,240),arc('Дуга 45° на новом круге',8,45)],
      [('Каков знаменатель несократимой доли для α=60°?','6','Сократи 60/360.'),('Каков коэффициент при π у новой дуги?','2','Возьми восьмую часть от 16.')],[118,119],
      'Выделена дуга AB, а не отрезок AB. T — центр, UW — единица длины.')
    return [first,second,third]


def units():
    one=ask(11,'Покажи один радиан','Какой центральный угол называется углом в один радиан? Как проверить это измерением?',
      'Угол в один радиан стягивает дугу, длина которой равна радиусу. При общем увеличении окружности длины и дуги, и радиуса умножаются на одно число, так что сам угол остаётся прежним.',
      'Сравни радиус с гибкой дугой между A и B. Равенство радиуса и прямой хорды задаёт 60°, а не один радиан.',[
      ('Отметь длину радиуса на дуге','При радиусе 2 длина дуги 2 означает ровно 1 рад. В градусах это около 57,3°, немного меньше 60°.','Нельзя просто шагнуть циркулем расстоянием 2 по хорде.'),
      ('Различи дугу и хорду','При 60° хорда равна радиусу, но дуга равна πR/3 и длиннее R. При R=2 это 2π/3>2.','Выражение φ=l/R использует длину дуги.'),
      ('Сохрани один радиан','При новом R=5 тот же центральный угол отсекает дугу длиной 5. Отношение 5/5 снова равно 1.','Радианная мера — отношение двух длин в одинаковых единицах.')],
      [arc('Дуга и радиус по 2',2,180/pi),arc('Для сравнения угол 60°',2,60),arc('Один радиан при R=5',5,180/pi)],
      [('Какова радианная мера при l=2 и R=2?','1','Раздели 2 на 2.'),('Какова длина дуги одного радиана при R=5?','5','Умножь радианную меру на радиус.')],[119],
      'T — центр. Длина выделенной дуги AB сравнивается с TA, мерка UW постоянна.')
    two=ask(12,'Переводи градусы в радианы и обратно','Как связаны обе меры одного угла? Выведи формулу перехода в каждом направлении.',
      'Полуоборот — одновременно 180° и π радиан. Значит, α° соответствует φ=απ/180 радиан, а угол φ радиан равен 180φ/π градусов.',
      'Для перевода помни одну опору: 180°=π рад. Проверь направление множителя на этом значении.',[
      ('Уменьши полуоборот','Половина 180° — 90°, следовательно, половина π — π/2 радиан. Деление на один коэффициент сохраняет тот же угол в разных единицах.','Числа 90 и π/2 различны, но задают один и тот же поворот.'),
      ('Переведи в обратную сторону','Угол 2π/3 занимает две трети полуоборота, значит, равен 120°. Формула 180·(2π/3)/π даёт то же.','При переводе из радиан множитель π сокращается.'),
      ('Проверь большую дугу','Три четверти полного оборота — 270°, или 3π/2 рад. Используй дугу 270°, а не малую дугу 90° с теми же концами.','Полный оборот 2π рад служит дополнительной проверкой.')],
      [arc('Четверть полного оборота',3,90),arc('Угол 2π/3',3,120),arc('Три четверти полного оборота',4,270)],
      [('Сколько градусов в 2π/3 радиан?','120','Возьми две трети от 180.'),('Какой числитель у множителя π в радианной мере 270°, если знаменатель 2?','3','Подставь 270 в απ/180 и сократи.')],[119],
      'Радиусы TA и TB отмечают концы выделенной дуги. UW — единица длины.')
    three=ask(13,'Длина дуги в радианах','Как вычислить длину дуги, если известны R и радианная мера φ? Почему в формуле нет дополнительного множителя π/180?',
      'Определение радианной меры даёт φ=l/R, поэтому l=Rφ. Коэффициент π/180 необходим только на отдельном шаге перевода из градусов.',
      'Если угол уже дан в радианах, умножь его на радиус без повторного перевода.',[
      ('Сравни с единичным радиусом','Для φ=2 рад и R=1 длина дуги равна 2. Это верно по самому определению радианной меры.','Число 2 в этом шаге не означает 2°.'),
      ('Увеличь радиус при том же угле','Для φ=2 рад и R=3 путь по дуге равен 6. Отношение 6/3 восстанавливает заданный угол.','При одинаковых углах длины дуг пропорциональны радиусам.'),
      ('Проверь новую четверть оборота','Для R=8 и φ=π/2 длина 8·π/2=4π. Четверть полной длины 16π подтверждает это число.','Число π здесь входит в значение угла, а не в дополнительный коэффициент.')],
      [arc('Два радиана при R=1',1,360/pi),arc('Тот же угол при R=3',3,360/pi),arc('Угол π/2 при R=8',8,90)],
      [('Чему равен путь при R=3 и φ=2 рад?','6','Умножь 3 на 2.'),('Каков коэффициент при π для новой дуги?','4','Вычисли 8·π/2.')],[119],
      'По цветной дуге от A до B отсчитывается φ. UW — единичная мерка.')
    return [one,two,three]


def measures():
    vs=[inscribed('Шесть сторон вписанного многоугольника',3,6,True),inscribed('Двенадцать сторон',3,12,True),inscribed('Двадцать четыре стороны при R=5',5,24,True)]
    disk_area=ask(14,'Получи площадь круга','Выведи S=πR² через правильные вписанные многоугольники и объясни, какой предельный переход используется.',
      'Площадь правильного n-угольника равна Pₙrₙ/2. Когда число сторон растёт, периметр Pₙ стремится к 2πR, а апофема rₙ=R cos(180°/n) стремится к R. Площадь тоже стремится к площади круга: круг радиуса rₙ помещается в многоугольник, а многоугольник — в круг радиуса R; при rₙ/R→1 их площади сближаются по подобию. Получаем S=(2πR)R/2=πR².',
      'Периметр многоугольника приближает длину окружности, но высота треугольника — апофема. Объясни, почему оба множителя имеют нужные пределы.',[
      ('Запиши площадь многоугольника','Суммируй площади треугольников с вершиной T. Для шестиугольника высота TH чуть короче TA. Поэтому не заменяй её точно на R при конечном числе сторон.','Площадь конечного вписанного многоугольника меньше площади круга.'),
      ('Добавь стороны','У двенадцатиугольника апофема ближе к R. Отношение площадей внутреннего и внешнего кругов равно квадрату rₙ/R, поэтому оно стремится к единице.','Для этого отношения нужна лишь теорема о подобных площадях.'),
      ('Проверь итог на новом радиусе','В пределе S=πR². При R=5 площадь 25π; при удвоении радиуса площадь стала бы 100π.','Квадрат радиуса возникает из двух линейных множителей.')],
      [g for g,_ in vs],[('Сколько центральных треугольников у второго многоугольника?','12','Сосчитай его стороны.'),('Каков коэффициент при π у площади нового круга радиуса 5?','25','Возведи 5 в квадрат.')],[116,118,120],
      'Закрашен вписанный многоугольник. T — центр, TA=R, TH — апофема. Сравни расстояние между стороной и дугой при разных числах вершин.')
    m=disk_area['visualization']['model']
    for i,(v,(_,boundary)) in enumerate(zip(m['views'].values(),[vs[0],*vs,*vs],strict=True)):
        v['polygons']=[[k+'__v'+str(i) for k in boundary]]
    sectors=[disk('Угол 60° и R=3',3,60),disk('Большой сектор',3,60,'remainder'),disk('Четверть нового круга',4,90)]
    sector=ask(15,'Найди площадь кругового сектора','Что называют круговым сектором и как вывести его площадь по центральному углу?',
      'Сектор ограничен двумя радиусами и соединяющей их дугой. Доля площади равна доле полного оборота. Для α градусов S=πR²·α/360; для φ радиан та же доля равна φ/(2π), и S=R²φ/2.',
      'Назови, какую именно дугу выбрал. Два заданных радиуса задают два сектора, если не указать дугу.',[
      ('Отметь меньший сектор','Угол 60° даёт шестую часть круга. При R=3 её площадь равна 9π/6=3π/2.','Обе прямые границы сектора начинаются в T.'),
      ('Возьми дополнительную дугу','При тех же концах большая дуга имеет 300°, её сектор занимает 5/6 круга и имеет площадь 15π/2. Две площади дают 9π.','Для большого сектора нельзя подставлять угол меньшей дуги.'),
      ('Проверь новый радиус и угол','У сектора R=4 с углом 90° площадь 4π. В радианах этот угол π/2, поэтому R²φ/2 даёт то же значение.','Площадь измеряется в квадратных единицах.')],
      [g for g,_ in sectors],[('Сколько градусов у дополнительной дуги к 60°?','300','Вычти 60 из 360.'),('Чему равен коэффициент при π для нового сектора?','4','Возьми четверть от 16.')],[121],
      'Выделенная область включает центр T и ограничена радиусами. UW — единица длины.')
    segments=[disk('Сектор 90°',4,90),disk('Малый сегмент за хордой',4,90,'segment'),disk('Новый сегмент 60°',2,60,'segment')]
    segment=ask(16,'Отдели сегмент от сектора','Как узнать круговой сегмент по его границе и как вычислить его площадь?',
       'Сегмент ограничен одной хордой и одной из дуг между её концами. Для малой дуги его площадь равна площади сектора за вычетом площади треугольника с вершиной в центре. Для дуги 180° получается полукруг, для большой дуги можно вычесть меньший сегмент из всего круга.',
       'У сектора две прямые границы — радиусы. У сегмента одна прямая граница — хорда. Проверь, входит ли треугольник TAB в закрашенную часть.',[
       ('Определи вспомогательный сектор','При R=4 и угле 90° площадь сектора равна 4π. Радиусы перпендикулярны, площадь треугольника TAB равна 4·4/2=8.','Найти 4π — только первый шаг.'),
       ('Отсеки треугольник хордой','Второй рисунок показывает только малый сегмент. Его площадь 4π−8. Большой сегмент на той же хорде дополняет его до 16π.','Если прибавить треугольник, получится другая область.'),
       ('Проверь дугу 60°','При R=2 малый сектор имеет площадь 2π/3. Центральный треугольник равносторонний, его площадь √3. Поэтому малый сегмент имеет площадь 2π/3−√3.','У нового угла нельзя переносить формулу площади прямоугольного треугольника без синуса.')],
       [g for g,_ in segments],[('Чему равна площадь треугольника при R=4 и угле 90°?','8','Возьми половину произведения 4 на 4.'),('Каков коэффициент при √3 в площади нового равностороннего треугольника со стороной 2?','1','Вычисли 2²√3/4.')],[121],
       'T — центр. AB становится прямой границей сегмента. Сравни первую и вторую модели при одной и той же дуге. UW — единица.')
    for c,scenes in [(sector,sectors),(segment,segments)]:
        m=c['visualization']['model']
        for i,(v,(_,polys)) in enumerate(zip(m['views'].values(),[scenes[0],*scenes,*scenes],strict=True)):
            ids={name:k for k in v['points'] for name in m['labels'][k].split('=')}
            v['polygons']=[[ids.get(k,k+'__v'+str(i)) for k in pp] for pp in polys]
            if (c is sector and i in (3,6)) or (c is segment and i not in (3,6)):
                v['rightAngles']=[dict(vertex=ids['T'],a=ids['A'],b=ids['B'],size=1.4)]
    return [disk_area,sector,segment]


def build():return {'bookId':BOOK,'lessons':[*boundary(),*units(),*measures()]}


if __name__=='__main__':
    q=argparse.ArgumentParser();q.add_argument('--check',action='store_true')
    s=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if q.parse_args().check:assert OUT.read_text()==s
    else:OUT.write_text(s)
